entries[260202] = { ["name"] = "Visage of Akil'zon, Loa of Victory", ["text"] = "1\nVisage of Akil'zon, Loa of Victory\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nRequires Renown Rank 18 with the Amani Tribe." }
entries[260227] = { ["name"] = "Frostbitten Tabard", ["text"] = "Quest Item\n\"Well-worn and battered, this tabard is mostly recognizable under all the dust and frost.\"" }
entries[260228] = { ["name"] = "Galactic Gladiator's Goredrake", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Originating from the void, fully armored and ready for combat.\"\nAchievement:\nGladiator: Midnight Season 1\nCategory:\nPlayer vs. Player" }
entries[260231] = { ["name"] = "Lucent Hawkstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A loyal creature of Thalassian nobility, it finds comfort holed up in the Magisters' Terrace.\"\nDrop:\nDegentrius\nZone:\nMagister's Terrace (Mythic)\n\nDrop:\nChallenger's Cache\nZone:\nMagister's Terrace" }
entries[260232] = { ["name"] = "Thalassian Skeleton Key", ["text"] = "Use: Allows opening of locks that require up to 90 lockpicking skill. The lockpick is consumed in the process.\nSell Price:" }
entries[260233] = { ["name"] = "Emerald Hawkstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Its rider died during battle, and so the saddle is passed to you.\"\nWorld Quest:\nThe Battle of the Bridge\nZone:\nSilvermoon City" }
entries[260235] = { ["name"] = "Umbral Plume", ["text"] = "Binds when picked up\nUnique-Equipped: Plume of Belo'ren (1)\nTrinket\n+9 [Agility or Strength]\nEquip: The Plume's gloom grants you 21 Critical Strike, waning over 60 sec before returning to full darkness. The Plume's power also regenerates while out of combat.\nUse: While out of combat, invoke the Plume's dual nature to transform it into a Radiant Plume. (5 Min Cooldown)\nSell Price:" }
