entries[260270] = { ["name"] = "Bog Legs", ["text"] = "Use: Restores 6% of your maximum health every second over 20 sec. Must remain seated while eating.\n\"An assortment of fried, leg-meat drumsticks. Meats include amazard, toad, boggorm, and all other manner of Leech Bog dwellers.\"\nSell Price:" }
entries[260271] = { ["name"] = "Root Juice", ["text"] = "Use: Restores 6% of your maximum mana every second over 20 sec. Must remain seated while drinking.\n\"Hand-squeezed roots, tubors, and toadstools sourced throughout Zul'Aman's clilffsides.\"\nSell Price:" }
