entries[262705] = { ["name"] = "Vicious Snapvine", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. This Snapvine is always wanting to see more of the world and be fed.\"\nTrading Post" }
entries[262706] = { ["name"] = "Ferocious Snapvine", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. The fruit from this beast is especially delicious when baked in a pie.\"\nTrading Post" }
entries[262707] = { ["name"] = "Blooded Snapvine", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. The distinct, bold coloring means the creature has eaten recently.\"\nTrading Post" }
entries[262708] = { ["name"] = "Savage Snapvine", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. Why would anyone want to find one of those things, much less ride one? But the fruit is good.\"\nTrading Post" }
