entries[262741] = { ["name"] = "\"Dispelling Leap\" Kit", ["text"] = "Binds to Warband\nUnique\nUse: Allows you to use the \"Dispelling Leap\" ability when playing as a Spellbreaker.\n\nDispelling Leap : Jump to a location, dispelling the illusions of Hiders around the area of impact." }
